export const TOWNHOUSE_LOT_DATA_URI = "data:image/jpeg;base64,";
export const TOWNHOUSE_LOT_WIDTH = 500;
export const TOWNHOUSE_LOT_HEIGHT = 779;

// Two-row layout. North row (housing frame, top-right slot) — same
// dir="up" orientation as the Mansion/Suburban House: native y=0 is the
// far-from-road content, native y=HEIGHT is nearest the road.
//
// The gap between the two rows used to be a generic paver+hedge tile
// reused from the front photo. Replaced with a real backyard-fence-
// backyard sequence (patio/clothesline/garden from a dedicated backyard
// photo, then its own wooden fence, then the same yard mirrored) so the
// two rows read as sharing a real rear property line instead of an
// arbitrary strip — scaled down substantially (the yard's natural
// height would have pushed the far row almost entirely off-screen) to
// keep the far row about as visible as before.
//
// Far row (back facade, roofline cut at the very top), near row (front
// facade, close to the gate with a minimal walkway), and the gate/fence
// itself are otherwise unchanged.
export const TOWNHOUSE_LOT_GROUND_STRIP_TOP = 0;
export const TOWNHOUSE_LOT_GROUND_STRIP_HEIGHT = 1;

// Brightened to match the Mansion's lighter, more vivid look — the
// street's night-lit lots had drifted noticeably darker/muddier than the
// Mansion by comparison. Gamma-lifted (brightness x1.12, gamma 0.85) and
// mildly re-saturated (x1.05) rather than reshot, same programmatic
// approach as the day-to-night grading in trailerLot.ts, just brightening
// instead of darkening. Applied directly to the already-composited photo
// (front row, backyard gap, gate — see the layout note above), so no
// other constants change.
